-- Seed: agent vocabulary for flow control (design docs/vertex-rebuild/designs/flow-control-signals, pull request 2).
-- Three terms with source "none": Vertex has no stored query for them; terms_query answers "Not available." with the
-- description, which points the agent to the MCP tool flow_control. Not certified. The texts hold no rule number (the
-- tool answer carries the rules). Existing ids are never overwritten.
INSERT INTO "semantic_terms" ("id", "label", "description", "synonyms", "source", "feed_path", "mapped_columns", "unit", "params", "certified") VALUES
  ('options_net_drift', 'Options net drift', 'Options net drift (vendor: QuantData): for one option ticker (SPY, QQQ, SPX or NDX) and one minute, the premium in US dollars of options bought at the ask minus the premium sold at the bid, separately for calls and for puts, for out-of-the-money options without complex, tied, floor and cancelled trades (filter profile otm-clean.v1). Sign: a positive call-minus-put value means call buying leads (bullish); a negative value means put buying leads (bearish). Horizon: the regular options session, 09:30 to 16:15 New York, in one-minute buckets; every running sum starts at 09:30 and is given for all expiries (total) and for same-day expiries (zero_dte). Coverage: the vendor series is complete for this filter; when the same-day part is missing, the series has partsStatus partial and partsDetail says which part. This is not drift_level: drift_level is the drift of a paper forward monitor against its backtest. Vertex has no stored query for this term. Call the tool flow_control with group sp500 or nasdaq100 and read netDrift (totals, slopeUsdPerMinute, points). When the tool says no_data, give its reason and do not estimate. Research input only; not a trade instruction.', '["net drift", "net premium drift", "options premium flow", "call minus put premium"]'::jsonb, 'none', null, '[]'::jsonb, 'USD', '[]'::jsonb, false),
  ('futures_deep_trades', 'Futures deep trades', 'Futures deep trades: single large trade prints on the futures ES (S&P 500) and NQ (Nasdaq 100). One deep trade is one print at or above the deep-trade size limit of its market; the limit in force is the field limitSize of the tool answer. Unit: contracts. Sign: buy means the print was signed as buyer-initiated, sell as seller-initiated; netVolume is buy volume minus sell volume and is positive when large buying leads. Horizon: the regular session, 09:30 to 16:00 New York; sums start at 09:30. Coverage caveat: the tape is sampled, not complete. The field coverage gives the seconds seen and their approximate share of the rule window; busy periods are seen least, because each fetch holds a fixed number of prints. Every sum is a sum of the sampled trades only, so it is a lower bound, and a minute that was not sampled is a gap, not zero. Sides come from the quote rule where the sampled quotes cover a print, else from the tick rule, which follows the last price change; each trade carries its signing method. Vertex has no market-by-order data, so the size of resting orders is not shown. Vertex has no stored query for this term. Call the tool flow_control with group sp500 (ES) or nasdaq100 (NQ) and read deepTrades and futures. The futures side itself has no state on a sampled tape (reason sampled_tape): report the trades and the coverage, not a state. Research input only; not a trade instruction.', '["deep trades", "large futures trades", "large futures prints", "big futures prints"]'::jsonb, 'none', null, '[]'::jsonb, 'contracts', '[]'::jsonb, false),
  ('flow_control_state', 'Flow control state (who is in control)', 'Flow control state: for one index group (sp500: ES futures with SPX and SPY options; nasdaq100: NQ futures with QQQ and NDX options), one state for the options side (from options_net_drift) and one for the futures side. States: buyers, sellers, balanced, mixed or no_data; no_data always has a reason (market_closed, source_unavailable, storage_failed, stale, gap, session_start, sampled_tape, not_collected). The futures state needs the full futures tape with quote-rule sides. Vertex samples the tape, so in this version the futures side is no_data with the reason sampled_tape, and the agreement of the two sides is not_comparable: it is not computed. The deep trades are still listed (see futures_deep_trades). Sign: buyers is bullish, sellers is bearish. Unit: none; the options side carries its measured ratio and the limit it is compared with, and the field rules holds every number of the rule with its version. Horizon: a trailing window inside the regular session, anchored at 09:30 New York; since is the start of the present state. Coverage caveat: the options side is complete for the vendor filter; the futures side has no state on a sampled tape. The field study says whether the continuation rule was tested and with what verdict. Vertex has no stored query for this term. Call the tool flow_control with group sp500 or nasdaq100. Read the enums, not the label text. For a no_data side report the reason and do not estimate. A state describes recent flow; it is never a trade instruction.', '["who is in control", "control state", "buyers in control", "sellers in control"]'::jsonb, 'none', null, '[]'::jsonb, 'state', '[]'::jsonb, false)
ON CONFLICT ("id") DO NOTHING;
